//+------------------------------------------------------------------+  
//|                                                       
//| Exact rules: Buy/Sell Stop 2 pips away, 5s expire, trail 1 pip   |  
//+------------------------------------------------------------------+

\#include <Trade\\Trade.mqh>  
CTrade trade;  // Use CTrade for easier operations  
input double LotSize = 0.01;  // Lot size  
ulong buy\_stop\_ticket  = 0;  
ulong sell\_stop\_ticket = 0;  
datetime last\_place\_time = 0;  
//+------------------------------------------------------------------+  
//| Expert tick function                                             |  
//+------------------------------------------------------------------+  
void OnTick()  
{  
   // Clean up expired pendings (rule 4)  
   CheckAndDeleteExpiredPendings();  
   // If no open position AND no pending orders left → place new ones (rule 5 + 1)  
   if (PositionsTotal() == 0 && buy\_stop\_ticket == 0 && sell\_stop\_ticket == 0)  
   {  
PlaceNewOrders();  
   }  
   // If we have an open position (rule 2 & 3)  
   if (PositionsTotal() == 1)  
   {  
// Delete opposite pending if still there (rule 2)  
DeleteOppositePending();  
// Trail SL if in profit >= 1 pip (rule 3)  
TrailSLBy1Pip();  
   }  
}  
//+------------------------------------------------------------------+  
//| Place new Buy Stop + Sell Stop (rule 1)                          |  
//+------------------------------------------------------------------+  
void PlaceNewOrders()  
{  
   double ask = SymbolInfoDouble(\_Symbol, SYMBOL\_ASK);  
   double bid = SymbolInfoDouble(\_Symbol, SYMBOL\_BID);  
   double pip\_value = 0.10;           // 1 pip = 0.10 price  
   double distance   = 2.0 \* pip\_value;   // 2 pips = 0.20  
   double sl\_tp\_dist = 20.0 \* pip\_value;  // 20 pips = 2.00  
   double buy\_price  = NormalizeDouble(ask + distance, \_Digits);  
   double sell\_price = NormalizeDouble(bid - distance, \_Digits);  
   double buy\_sl  = NormalizeDouble(buy\_price  - sl\_tp\_dist, \_Digits);  
   double buy\_tp  = NormalizeDouble(buy\_price  + sl\_tp\_dist, \_Digits);  
   double sell\_sl = NormalizeDouble(sell\_price + sl\_tp\_dist, \_Digits);  
   double sell\_tp = NormalizeDouble(sell\_price - sl\_tp\_dist, \_Digits);  
   // Use GTC (no broker expiration) - EA deletes after 5s  
   datetime expire = 0;  // ignored for GTC  
   // Buy Stop  
   if (trade.BuyStop(LotSize, buy\_price, \_Symbol, buy\_sl, buy\_tp, ORDER\_TIME\_GTC, expire, "Buy Stop"))  
   {  
buy\_stop\_ticket = trade.ResultOrder();  
last\_place\_time = TimeCurrent();  
PrintFormat("Buy Stop PLACED at %.3f | SL: %.3f | TP: %.3f", buy\_price, buy\_sl, buy\_tp);  
   }  
   else  
   {  
Print("BuyStop FAILED: ", trade.ResultRetcodeDescription(), " (code ", trade.ResultRetcode(), ")");  
   }  
   // Sell Stop  
   if (trade.SellStop(LotSize, sell\_price, \_Symbol, sell\_sl, sell\_tp, ORDER\_TIME\_GTC, expire, "Sell Stop"))  
   {  
sell\_stop\_ticket = trade.ResultOrder();  
last\_place\_time = TimeCurrent();  
PrintFormat("Sell Stop PLACED at %.3f | SL: %.3f | TP: %.3f", sell\_price, sell\_sl, sell\_tp);  
   }  
   else  
   {  
Print("SellStop FAILED: ", trade.ResultRetcodeDescription(), " (code ", trade.ResultRetcode(), ")");  
   }  
}  
//+------------------------------------------------------------------+  
//| Delete both pendings if expired (rule 4)                         |  
//+------------------------------------------------------------------+  
void CheckAndDeleteExpiredPendings()  
{  
   if ((buy\_stop\_ticket > 0 || sell\_stop\_ticket > 0) && TimeCurrent() - last\_place\_time >= 5)  
   {  
if (buy\_stop\_ticket > 0)  trade.OrderDelete(buy\_stop\_ticket);  
if (sell\_stop\_ticket > 0) trade.OrderDelete(sell\_stop\_ticket);  
buy\_stop\_ticket = sell\_stop\_ticket = 0;  
   }  
}  
//+------------------------------------------------------------------+  
//| Delete opposite pending once position opens (rule 2)             |  
//+------------------------------------------------------------------+  
void DeleteOppositePending()  
{  
   if (buy\_stop\_ticket > 0 || sell\_stop\_ticket > 0)  
   {  
for (int i = PositionsTotal() - 1; i >= 0; i--)  
{  
ulong ticket = PositionGetTicket(i);  
if (ticket == 0) continue;  
if (PositionGetString(POSITION\_SYMBOL) != \_Symbol) continue;  
ENUM\_POSITION\_TYPE pos\_type = (ENUM\_POSITION\_TYPE)PositionGetInteger(POSITION\_TYPE);  
if (pos\_type == POSITION\_TYPE\_BUY && sell\_stop\_ticket > 0)  
{  
trade.OrderDelete(sell\_stop\_ticket);  
sell\_stop\_ticket = 0;  
}  
else if (pos\_type == POSITION\_TYPE\_SELL && buy\_stop\_ticket > 0)  
{  
trade.OrderDelete(buy\_stop\_ticket);  
buy\_stop\_ticket = 0;  
}  
}  
   }  
}  
//+------------------------------------------------------------------+  
//| Trail SL by 1 pip as soon as +1 pip profit (rule 3)              |  
//+------------------------------------------------------------------+  
void TrailSLBy1Pip()  
{  
   double pip\_value = 0.10;  // Your 1 pip = 0.10  
   for (int i = PositionsTotal() - 1; i >= 0; i--)  
   {  
ulong ticket = PositionGetTicket(i);  
if (ticket == 0) continue;  
if (PositionGetString(POSITION\_SYMBOL) != \_Symbol) continue;  
double open\_price = PositionGetDouble(POSITION\_PRICE\_OPEN);  
double current\_sl = PositionGetDouble(POSITION\_SL);  
ENUM\_POSITION\_TYPE pos\_type = (ENUM\_POSITION\_TYPE)PositionGetInteger(POSITION\_TYPE);  
double new\_sl = 0;  
if (pos\_type == POSITION\_TYPE\_BUY)  
{  
double bid = SymbolInfoDouble(\_Symbol, SYMBOL\_BID);  
double profit = bid - open\_price;  
if (profit >= pip\_value)  // >= 1 pip in profit  
{  
new\_sl = NormalizeDouble(bid - pip\_value, \_Digits);  // trail 1 pip behind  
if (new\_sl > current\_sl + \_Point)  // only move if improvement  
{  
trade.PositionModify(ticket, new\_sl, PositionGetDouble(POSITION\_TP));  
}  
}  
}  
else if (pos\_type == POSITION\_TYPE\_SELL)  
{  
double ask = SymbolInfoDouble(\_Symbol, SYMBOL\_ASK);  
double profit = open\_price - ask;  
if (profit >= pip\_value)  
{  
new\_sl = NormalizeDouble(ask + pip\_value, \_Digits);  
if (new\_sl < current\_sl - \_Point || current\_sl == 0)  
{  
trade.PositionModify(ticket, new\_sl, PositionGetDouble(POSITION\_TP));  
}  
}  
}  
   }  
}
